#!/usr/bin/env python3
# luxarch:commit-leftover-check hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""After a commit, surface tracked files that are STILL modified.

The safety net behind no-silenced-staging.py: if a staging step failed quietly (or a file was
simply forgotten) the commit lands PARTIAL and the dropped file shows as ` M`. A green local
build hides it, because it builds the working tree, not the commit. The status is read where git
committed: the agent's checkout, or the directory a `git -C <dir> commit` names.

Advisory, never blocking — leaving files out is often deliberate; this just makes it a
conscious choice rather than a discovery three commits later.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import MalformedEvent, git_calls
from _ledger import event_command, event_cwd, git_at, tree_dir


def main() -> int:
    cmd = event_command()
    try:
        calls = [g for g in git_calls(cmd) if g.sub == "commit"]
    except MalformedEvent:
        calls = []
    if calls:
        dirs = list(
            dict.fromkeys(event_cwd() / g.cwd if g.cwd else tree_dir() for g in calls)
        )
    elif re.search(r"\bgit\s+commit\b", cmd):
        dirs = [tree_dir()]
    else:
        return 0
    modified = [
        ln
        for where in dirs
        for ln in git_at(where, "status", "--porcelain").splitlines()
        if ln[:2].strip() in ("M", "MM", "AM")
    ]
    if not modified:
        return 0
    print(
        "Heads-up — tracked files are still modified after that commit:\n"
        + "\n".join(f"  {m}" for m in modified[:10])
        + "\nIf any of those belonged in the commit, the staging step dropped them.",
        file=sys.stderr,
    )
    return 0


sys.exit(main())
